import { S3Client } from "@aws-sdk/client-s3"
import { PutObjectCommand, DeleteObjectCommand, GetObjectCommand } from "@aws-sdk/client-s3"
import env from "../config/env"
import { ulid } from "ulid"
import { CE_BAD_REQUEST } from "./Error"

class AWS {
  private s3Client: S3Client = new S3Client({
    region: env.AWS_REGION,
    credentials: {
      accessKeyId: env.AWS_ACCESS_KEY!,
      secretAccessKey: env.AWS_SECRET_KEY!,
    },
  })

  private s3Bucket: string = env.AWS_S3_BUCKET_NAME!

  private getExtensionFromMimeType(mimeType: string): string {
  const extensions: { [key: string]: string } = {
    'image/jpeg': '.jpg',
    'image/jpg': '.jpg',
    'image/png': '.png',
    'image/gif': '.gif',
    'image/webp': '.webp',
    'image/svg+xml': '.svg',
    'application/pdf': '.pdf',
    'text/plain': '.txt',
  }
  return extensions[mimeType] || '.jpg'
  }

  async uploadBase64(base64Image: string, fileName?: string, folder?: string) {
    try {

      if (!base64Image) throw new CE_BAD_REQUEST('No image provided')
        
      let contentType = "image/jpeg" // default
      let base64String = base64Image

      if (base64Image.startsWith("data:")) {
        const matches = base64Image.match(/^data:([^;]+);base64,(.+)$/)
        if (matches) {
          contentType = matches[1]
          base64String = matches[2]
        }
      }

      // Convert base64 to buffer
      const buffer = Buffer.from(base64String, "base64")

      // Generate filename if not provided
      const fileExtension = this.getExtensionFromMimeType(contentType)
      const finalFileName = fileName || `image-${Date.now()}${fileExtension}`

      // Upload to S3
      const key = folder ? await this.uploadToFolder(buffer, finalFileName, folder, contentType) : await this.uploadToFolder(buffer, finalFileName, 'uploads', contentType)

      // Since bucket is public, use public URL
      const publicUrl = this.getPublicUrl(key)
      console.log(publicUrl)
      return publicUrl;

    } catch (error) {
      console.error("Base64 upload error:", error)
      throw new CE_BAD_REQUEST(`Failed to upload image: ${error.message}`)
    }
  }

  getPublicUrl(key: string): string {
    return `https://${this.s3Bucket}.s3.${env.AWS_REGION}.amazonaws.com/${key}`
  }


  async uploadToFolder( buffer: Buffer, fileName: string, folder: string, contentType: string = "application/octet-stream" ): Promise<string> {
    try {
      const key = `${folder}/${ulid()}-${fileName}`

      const command = new PutObjectCommand({
        Bucket: this.s3Bucket,
        Key: key,
        Body: buffer,
        ContentType: contentType,
        // Optional: Set file permissions
        ACL: "private", // or "public-read"
      })

      await this.s3Client.send(command)
      console.log("File uploaded to folder:", key)
      return key

    } catch (error) {
      console.error("Error uploading to folder:", error)
      throw new Error("Failed to upload file to S3 folder")
    }
  }
}

export default AWS;

